# claims voided with it.
respond:
  class: net.officefloor.hq.app.voidreason.RespondWithVoidReasons
  govern: [ readonly-transaction ]
-- The sheet's void reasons: each (trimmed, not blank) at most once, kept in the order added. While a sheet has any,
-- voiding a claim needs one of them; claim_void_reason keeps the reason each claim was voided with.
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    reason   VARCHAR(200) NOT NULL,
    CONSTRAINT void_reason_unique UNIQUE (sheet_id, reason)
);

CREATE TABLE claim_void_reason (
    claim_id BIGINT       NOT NULL PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    reason   VARCHAR(200) NOT NULL
);
CREATE INDEX claim_void_reason_sheet ON claim_void_reason (sheet_id, reason);
-- A person's aliases: each kept without surrounding spaces; alias_key is the alias as names are compared (lower-cased).
-- An alias is unique on the sheet, and the app keeps it apart from every person's name there too.
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(500) NOT NULL,
    alias_key VARCHAR(500) GENERATED ALWAYS AS (LOWER(alias))
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);

